const ShopItem* shopItems(std::size_t& n) { n = sizeof(kShopItems) / sizeof(kShopItems[0]) - 1; return kShopItems; }
const Npc* npcs(std::size_t& n) { n = sizeof(kNpcs) / sizeof(kNpcs[0]) - 1; return kNpcs; }
const Warp* warps(std::size_t& n) { n = sizeof(kWarps) / sizeof(kWarps[0]) - 1; return kWarps; }
int attrFix(int level, int atk, int def) { return kAttr[((level - 1) * 10 + atk) * 10 + def]; }
const Mob* mobs(std::size_t& n) { n = sizeof(kMobs) / sizeof(kMobs[0]); return kMobs; }
const Item* items(std::size_t& n) { n = sizeof(kItems) / sizeof(kItems[0]); return kItems; }
const Drop* drops() { return kDrops; }
const Spawn* spawns() { return kSpawns; }

